"""Authoritative mapping from engine completion/failure to typed run outcomes."""

from __future__ import annotations

from .result import CheckResult, Finding, RunResult


def classify_exception(exc: BaseException) -> str:
    if isinstance(exc, (KeyboardInterrupt, InterruptedError)):
        return "INTERRUPTED"
    name = type(exc).__name__.casefold()
    module = type(exc).__module__.casefold()
    if "tradingagents.dataflows" in module or "vendor" in module:
        return "DATA_FAILURE"
    if any(word in name for word in ("timeout", "ratelimit", "authentication", "apiconnection",
                                      "responseerror", "outputparser", "modelerror")):
        return "MODEL_FAILURE"
    if any(part in module for part in ("langchain", "openai", "anthropic", "google")):
        return "MODEL_FAILURE"
    if "vendor" in module or name in {"nomarketdataerror", "vendorunavailableerror",
                                      "vendornotconfigurederror"}:
        return "DATA_FAILURE"
    return "INTERNAL_ERROR"


class OutcomeFinalizer:
    def finalize(self, *, run_id: str, ticker: str, analysis_date: str,
                 input_mode: str, final_rating: str | None = None,
                 check_result: CheckResult | None = None,
                 exc: BaseException | None = None,
                 persistence_error: bool = False) -> RunResult:
        if persistence_error:
            exc_reason = "PERSISTENCE_ERROR"
        elif exc is not None:
            exc_reason = classify_exception(exc)
        else:
            exc_reason = None
        if exc_reason is not None or final_rating is None:
            reason = exc_reason or "INTERNAL_ERROR"
            return RunResult(
                run_id, ticker, analysis_date, input_mode, "INCOMPLETE", reason,
                None, "NOT_RUN", (), None, None,
            )
        check_result = check_result or CheckResult(
            "NEEDS_REVIEW", (Finding("CHECK_ERROR", detail="Output check was unavailable."),)
        )
        if check_result.output_check == "NOT_RUN":
            check_result = CheckResult(
                "NEEDS_REVIEW", (Finding("CHECK_ERROR", detail="Output check was unavailable."),)
            )
        return RunResult(
            run_id, ticker, analysis_date, input_mode, "COMPLETED", None,
            final_rating, check_result.output_check, check_result.findings, None, None,
        )

    def incomplete(self, *, run_id: str, ticker: str, analysis_date: str,
                   input_mode: str, reason: str) -> RunResult:
        return RunResult(run_id, ticker, analysis_date, input_mode, "INCOMPLETE",
                         reason, None, "NOT_RUN", (), None, None)

"""Trusted report body/envelope rendering for the shared run boundary."""

from __future__ import annotations

from tradingagents.reporting import _report_parts

from .checks import DISCLAIMER, NO_PORTFOLIO_NOTICE, render_provenance


def render_body(final_state: dict, context, redactor) -> tuple[str, list]:
    """Render narrative once, then redact it before checks and publication."""
    parts = _report_parts(final_state)
    sections = []
    for heading, _folder, written in parts:
        content = "\n\n".join(f"### {agent}\n{text}" for agent, _name, text in written)
        sections.append(f"## {heading}\n\n{content}")
    chunks = []
    if context.mode.value == "NO_PORTFOLIO":
        chunks.append(f"> {NO_PORTFOLIO_NOTICE}")
    if sections:
        chunks.extend(sections)
    else:
        chunks.append("## Analysis\n\nNo report sections were returned by the analysis workflow.")
    chunks.append(f"## Disclaimer\n\n{DISCLAIMER}")
    return redactor.scrub("\n\n".join(chunks)), parts


def build_envelope(metadata: dict, run_outcome: str, stop_reason: str | None,
                   final_rating: str | None, output_check: str,
                   findings: tuple, redactor) -> str:
    provenance = render_provenance(metadata)
    lines = [
        f"# Trading Analysis Report: {metadata['ticker']}", "", provenance,
        f"- Run outcome: {run_outcome}",
    ]
    if stop_reason:
        lines.append(f"- Stop reason: {stop_reason}")
    if final_rating is not None:
        lines.append(f"- Final Portfolio Manager rating: {final_rating}")
    lines.append(f"- Output check: {output_check}")
    if findings:
        lines.append("- Findings:")
        lines.extend(f"  - {finding.rule}: {finding.detail}" for finding in findings)
    return redactor.scrub("\n".join(lines) + "\n\n")


def verify_envelope_header_matches(envelope: str, trusted: dict) -> bool:
    """Check each trusted provenance line appears unchanged in the envelope."""
    return all(line in envelope.splitlines() for line in render_provenance(trusted).splitlines())

